<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Physics Playground</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #1a1a2e;
    color: #e0e0e0;
    font-family: Arial, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    gap: 16px;
    padding: 20px;
  }
  h1 {
    font-size: 1.5rem;
    color: #a78bfa;
    letter-spacing: 2px;
  }
  #controls {
    display: flex;
    gap: 12px;
  }
  button {
    padding: 10px 22px;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.2s, transform 0.1s;
    font-weight: bold;
  }
  button:active { transform: scale(0.96); }
  #drop {
    background: #7c3aed;
    color: #fff;
  }
  #drop:hover { background: #6d28d9; }
  #play {
    background: #059669;
    color: #fff;
  }
  #play:hover { background: #047857; }
  #play.paused {
    background: #b45309;
  }
  #play.paused:hover { background: #92400e; }
  #clear {
    background: #dc2626;
    color: #fff;
  }
  #clear:hover { background: #b91c1c; }
  #sim {
    border: 2px solid #4c1d95;
    border-radius: 4px;
    cursor: crosshair;
    display: block;
    box-shadow: 0 0 30px rgba(124, 58, 237, 0.4);
  }
  #info {
    font-size: 0.85rem;
    color: #9ca3af;
  }
</style>
</head>
<body>
<h1>⚽ Physics Playground</h1>
<div id="controls">
  <button id="drop">Drop Ball</button>
  <button id="play">Pause</button>
  <button id="clear">Clear</button>
</div>
<canvas id="sim" width="600" height="500"></canvas>
<div id="info">Click the canvas to add a ball</div>

<script>
(function() {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  const GRAVITY = 0.4;
  const RESTITUTION = 0.78;
  const FRICTION = 0.995;
  const MIN_R = 10;
  const MAX_R = 28;

  let _balls = [];
  let animRunning = true;
  let rafId = null;
  let lastTime = null;

  const COLORS = [
    '#f472b6', '#818cf8', '#34d399', '#fbbf24',
    '#60a5fa', '#a78bfa', '#f87171', '#4ade80',
    '#fb923c', '#38bdf8'
  ];
  let colorIdx = 0;

  function randomColor() {
    const c = COLORS[colorIdx % COLORS.length];
    colorIdx++;
    return c;
  }

  function addBall(x, y, vx = 0, vy = 0, r) {
    if (r === undefined || r === null) {
      r = MIN_R + Math.random() * (MAX_R - MIN_R);
    }
    // Clamp position inside canvas
    const cx = Math.min(Math.max(x, r), W - r);
    const cy = Math.min(Math.max(y, r), H - r);
    _balls.push({
      x: cx, y: cy,
      vx: vx, vy: vy,
      r: r,
      color: randomColor()
    });
  }

  function clear() {
    _balls = [];
    draw();
  }

  function balls() {
    return _balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r }));
  }

  function step(dt = 1) {
    for (let b of _balls) {
      // Apply gravity
      b.vy += GRAVITY * dt;

      // Apply friction (horizontal damping in air)
      b.vx *= Math.pow(FRICTION, dt);

      // Move
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      // Bounce off left wall
      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx = Math.abs(b.vx) * RESTITUTION;
      }
      // Bounce off right wall
      if (b.x + b.r > W) {
        b.x = W - b.r;
        b.vx = -Math.abs(b.vx) * RESTITUTION;
      }
      // Bounce off top
      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy = Math.abs(b.vy) * RESTITUTION;
      }
      // Bounce off bottom (floor)
      if (b.y + b.r > H) {
        b.y = H - b.r;
        b.vy = -Math.abs(b.vy) * RESTITUTION;
        // Extra horizontal friction on floor contact
        b.vx *= 0.98;
      }

      // Hard clamp to stay in bounds (safety net against tunneling)
      b.x = Math.min(Math.max(b.x, b.r), W - b.r);
      b.y = Math.min(Math.max(b.y, b.r), H - b.r);
    }
    draw();
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // Background
    ctx.fillStyle = '#0f0f23';
    ctx.fillRect(0, 0, W, H);

    // Grid lines (subtle)
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let gx = 0; gx < W; gx += 50) {
      ctx.beginPath(); ctx.moveTo(gx, 0); ctx.lineTo(gx, H); ctx.stroke();
    }
    for (let gy = 0; gy < H; gy += 50) {
      ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(W, gy); ctx.stroke();
    }

    for (let b of _balls) {
      // Shadow
      ctx.beginPath();
      ctx.arc(b.x + 2, b.y + 3, b.r, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.fill();

      // Ball gradient
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, lighten(b.color, 0.6));
      grad.addColorStop(0.5, b.color);
      grad.addColorStop(1, darken(b.color, 0.5));

      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      // Shine
      const shine = ctx.createRadialGradient(
        b.x - b.r * 0.3, b.y - b.r * 0.35, b.r * 0.05,
        b.x - b.r * 0.2, b.y - b.r * 0.2, b.r * 0.55
      );
      shine.addColorStop(0, 'rgba(255,255,255,0.45)');
      shine.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = shine;
      ctx.fill();
    }

    // Ball count
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    ctx.font = '12px Arial';
    ctx.fillText(`Balls: ${_balls.length}`, 8, 16);
  }

  function lighten(hex, amount) {
    return adjustColor(hex, amount);
  }
  function darken(hex, amount) {
    return adjustColor(hex, -amount);
  }
  function adjustColor(hex, amount) {
    let r = parseInt(hex.slice(1, 3), 16);
    let g = parseInt(hex.slice(3, 5), 16);
    let b = parseInt(hex.slice(5, 7), 16);
    r = Math.min(255, Math.max(0, Math.round(r + 255 * amount)));
    g = Math.min(255, Math.max(0, Math.round(g + 255 * amount)));
    b = Math.min(255, Math.max(0, Math.round(b + 255 * amount)));
    return `rgb(${r},${g},${b})`;
  }

  function animate(ts) {
    if (!animRunning) return;
    if (lastTime === null) lastTime = ts;
    const elapsed = ts - lastTime;
    lastTime = ts;
    // Cap dt to avoid huge jumps
    const dt = Math.min(elapsed / 16.67, 3);
    step(dt);
    rafId = requestAnimationFrame(animate);
  }

  function startAnimation() {
    if (rafId) cancelAnimationFrame(rafId);
    lastTime = null;
    rafId = requestAnimationFrame(animate);
  }

  // Controls
  const playBtn = document.getElementById('play');
  const dropBtn = document.getElementById('drop');
  const clearBtn = document.getElementById('clear');

  playBtn.addEventListener('click', () => {
    animRunning = !animRunning;
    if (animRunning) {
      playBtn.textContent = 'Pause';
      playBtn.classList.remove('paused');
      startAnimation();
    } else {
      playBtn.textContent = 'Play';
      playBtn.classList.add('paused');
      if (rafId) cancelAnimationFrame(rafId);
      rafId = null;
    }
  });

  dropBtn.addEventListener('click', () => {
    const x = W / 2 + (Math.random() - 0.5) * W * 0.5;
    const y = 30;
    const vx = (Math.random() - 0.5) * 4;
    addBall(x, y, vx, 0);
    if (!animRunning) draw();
  });

  clearBtn.addEventListener('click', () => {
    clear();
  });

  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    const vx = (Math.random() - 0.5) * 6;
    const vy = (Math.random() - 0.5) * 3;
    addBall(x, y, vx, vy);
    if (!animRunning) draw();
  });

  // Expose API
  window.sim = {
    get w() { return W; },
    get h() { return H; },
    balls,
    addBall,
    clear,
    step
  };

  // Initial state: drop a few balls
  addBall(W * 0.3, 50, 2, 0);
  addBall(W * 0.6, 80, -1.5, 0);
  addBall(W * 0.5, 20, 0.5, 0);

  startAnimation();
})();
</script>
</body>
</html>
